insert into product_details (product_id, specs_description, specs_left, specs_right, applications, faqs)
values (
  'camera-termografica-bt-600b',
  'A BT-600B é o modelo topo da Linha B, para termografistas e equipes que precisam do máximo de detalhe com o mínimo de tempo em campo. Com 640x512 pixels, NETD <40mK e IFOV de 0,66 mrad na lente padrão, ela chega a 0,16 mrad com a lente opcional de 6°, o que permite medir com precisão isoladores, conexões e cabos em subestações e linhas de transmissão. O foco automático e o laser, que mede a distância até o alvo em até 40 m, deixam cada registro nítido e bem documentado. A câmera reconhece automaticamente a lente instalada, e a anotação por voz e os textos predefinidos ficam salvos com a imagem. Mede de -20°C a 410°C, com faixa opcional até 2.000°C, e tem proteção IP54.

